  "op.img2dataURI.name": "画像 → Base64/dataURI",
  "op.imageCompress.desc": "画像の再エンコード圧縮：品質 0-100 ＋ 任意の最大幅（最近傍で縮小）＋ JPEG/PNG/WebP 出力形式。JPEG/WebP はブラウザ canvas でエンコードし、PNG は全環境で利用可能。プレビュー表示＋ダウンロード",
  "op.imageGray.desc": "グレースケール化（Rec.601：0.299R+0.587G+0.114B、Pillow の 'L' モードと同一式でピクセル単位一致）またはしきい値二値化（0-255）。CTF ではカラー画像を平坦化するとビットプレーンや模様の手がかりが現れることがあります",
  "op.imagePixelate.desc": "モザイクのブロック平均：ブロックサイズごとに内部ピクセルの平均値を取ります（端の不完全ブロックは実面積で収縮平均）。ブロックサイズ 1-512",
  "op.imageFrosted.desc": "ボックスブラー：水平＋垂直の 2 パス分離畳み込みでガウスを近似。端のウィンドウは実ピクセルで収縮平均。半径 1-20",
  "op.imageSketch.desc": "鉛筆スケッチ 2 モード：dodge＝グレースケール反転をボックスブラー後、カラー覆い焼きで混合（古典的手法）；edge＝Sobel 演算子による輪郭抽出（白地に黒線）",
  "op.imageToText.desc": "輝度→文字グラデーション対応のアスキーアート：出力列数 20-400 で調整可（縦方向のステップは横の 2 倍）、3 種のグラデーション表（classic/blocks/bits）＋反転。プレーンテキストを出力",
  "op.gifCompose.desc": "複数画像を GIF89a に合成：先頭フレームにサイズ統一（scale/pad）＋フレーム遅延＋ループ回数。LZW 圧縮と NETSCAPE2.0 ループ拡張を自前実装し、中央値分割法で 256 色以下に量子化。GIF 多フレーム抽出の逆方向を閉じます",
  "op.img2dataURI.desc": "画像 → Base64 の生成方向：画像をドロップするとファイルヘッダーから MIME を判定し（PNG/JPG/GIF/BMP/WebP/ICO）、dataURI または素の base64 文字列を出力",
  "ui.plugin.mcpHowTitle": "使い方（ローカル stdio 型）",
  "ui.plugin.mcpHowIntro": "このツールボックスの MCP はローカル stdio サービスです。AI クライアントが設定に従ってローカルプロセスを起動します。設定に URL がないのは正常です。完全ローカル・オフライン動作・外部送信ゼロ。",
  "ui.plugin.mcpHowStep1": "このツールボックスのインストール先で実行：py 通用点我启动.py --mcp-config —— 本機の絶対パスを埋め込んだ接続設定 JSON が出力されます",
  "ui.plugin.mcpHowStep2": "出力された mcpServers JSON をそのまま AI クライアントの設定に貼り付けてください",
  "ui.plugin.mcpHowStep3": "クライアントを再起動し、ツール一覧に 6 個の ebctf_* ツールが現れれば接続成功です",
  "ui.plugin.mcpHowClients": "設定ファイルの場所：Claude Code＝プロジェクト直下の .mcp.json；Cursor＝.cursor/mcp.json（または設定内の MCP パネル）；Trae＝MCP 設定パネル；Codex / Cline＝各自の MCP 設定；Claude Desktop＝claude_desktop_config.json",
  "ui.plugin.mcpPromptTitle": "最小プロンプト（どの AI に貼っても接続が完了します）",
  "ui.plugin.mcpPromptPathPh": "インストール先（任意：入力するとより正確。空欄なら AI が自分で探します）",
  "ui.plugin.mcpPromptCopy": "最小プロンプトをコピー",
  "ui.plugin.mcpPromptCopied": "コピーしました。AI クライアントに貼り付けてください",
  "ui.plugin.mcpPromptHead": "「恒烈CTF编码工具箱」をあなたの MCP に接続してください：",
  "ui.plugin.mcpPromptDirFilled": "1) 本機のインストール先：{0}",
  "ui.plugin.mcpPromptDirAuto": "1) まず本機でのインストール先を特定してください（目印：通用点我启动.py と mcp/server.mjs が同じディレクトリにあります。見つからない、または複数ある場合は私に聞いてください）",
  "ui.plugin.mcpPromptRest": "2) そのディレクトリで `py 通用点我启动.py --mcp-config` を実行し、出力の mcpServers JSON をそのまま MCP 設定（.mcp.json / claude_desktop_config.json など）に書き込んでください。再起動後、6 個の ebctf_* ツールが現れるはずです。\n3) これはローカル stdio サービスで、完全ローカル・外部送信ゼロです。\nツール早見：ebctf_list_categories は全分類を一覧｜ebctf_list_ops はキーワード/分類でアルゴリズムを一覧｜ebctf_op_schema はパラメータ schema を照会｜ebctf_detect はエンコードをスマート判定｜ebctf_run_op は指定アルゴリズムを実行｜ebctf_magic_decode は一発スマート復号（多段チェーン対応）。",
  "ui.rand.externalNote": "この op の乱数は同梱の第三者ライブラリ（{0}）がライブラリ内部で生成するため、統一乱数源を経由せず、「暗号強度の強化」の制御対象外です。",
  "ui.rand.off": "オフ（システム乱数源 crypto.getRandomValues を使用）。",
  "ui.rand.mouseAux": "マウスエントロピーを追加",
  "ui.rand.mouseAuxDesc": "ダイアログ内でマウスを動かしてローカルのエントロピーを採取し、現在のモードに上乗せします（増えるだけで減らず、結果は元のモードより弱くなりません）。信頼できないシステム向け：システム乱数源を単一障害点にしないため。",
  "ui.rand.mouseStatus": "マウスエントロピー",
