  "op.caesar.desc": "指定したシフト量で変換（encode は +shift、decode は -shift）。モードで漸増/漸減シーザー（x 文字目を shift±x だけシフト）に切替可能。文字セットは「アルファベットのみ」または「印刷可能 ASCII 33-126 の全文字シフト（非文字も動く変種向け）」を選択できます",
  "op.spriteSheet.name": "スプライトシート変換",
  "op.spriteSheet.desc": "スプライトシート ↔ 連番フレーム変換：split は N 列 × M 行のグリッドをフレームごとの PNG に分割（行優先、frame_000 開始）。merge は複数フレーム（先頭フレームをメイン入力、追加欄に 1 行 1 枚の dataURL）を 1 行の枚数に従ってグリッドに合成し、末尾の空きは透明で埋めます。純 JS の PNG で全環境対応",
  "ui.op.pendingRun": "【{0}】準備完了、自動実行はしていません。\n下の「変換」ボタンをクリックすると開始します。",
